from pathlib import Path

from bluesky import RunEngine
from nexusformat import nexus

from bluesky_nexus.callbacks import BaseCallback, HdfWriterCallback


# Make our own callback which prints the nexus structure generated by each plan.
class NewCallbackWhichPrintsTheNexusStructure(BaseCallback):
    def process_nexus_structure(self, generated_structure: nexus.NXroot) -> None:
        print(generated_structure.tree)


RE = RunEngine()

# Will print the nexus structure generated for each bluesky plan.
RE.subscribe(NewCallbackWhichPrintsTheNexusStructure())

# Will output a hdf5 file for each bluesky plan.
RE.subscribe(HdfWriterCallback(Path(".")))
